/// <summary>
/// derived class for FEGIME export
/// </summary>
internal final class NDXSNGenDataFegime extends NDXSNGenData
{
}

Method.Source:
void pupulateData()
{
    NDXSNExportDataFegime::pupulateData(nDX_SalesNoteCustomer.nDX_SNSalesItemGroupCustomerTmp, signature, NDXCompanyBE::Niedax);
    this.fileName = nDX_SalesNoteCustomer.nDX_SNAlliance.SalesForAllianceId + '_NDX' + ".csv";
    super();

    NDXSNExportDataFegime::pupulateData(nDX_SalesNoteCustomer.nDX_SNSalesItemGroupCustomerTmp, signature, NDXCompanyBE::Kleinhuis);
    this.fileName = nDX_SalesNoteCustomer.nDX_SNAlliance.SalesForAllianceId + '_HKL' + ".csv";
    super();

    NDXSNExportDataFegime::pupulateData(nDX_SalesNoteCustomer.nDX_SNSalesItemGroupCustomerTmp, signature, NDXCompanyBE::Fintech);
    this.fileName = nDX_SalesNoteCustomer.nDX_SNAlliance.SalesForAllianceId + '_FIN' + ".csv";
    super();
}

void deleteGeneratedData()
{
    NDXSNExportDataFegime lNDXSNExportDataFegime;

    delete_from lNDXSNExportDataFegime
        where lNDXSNExportDataFegime.Signature == signature;
}
